"use client";
import type { ComponentProps, CSSProperties } from "react";
import { cn } from "./lib/cn";
import "./equalizer-bars.css";

export type EqualizerBarsProps = Omit<ComponentProps<"span">, "children"> & {
  /** Bars bounce while true and settle low when false. */
  playing?: boolean;
  bars?: 3 | 4 | 5;
  /** Read instead of "Playing" or "Paused". Pass an empty string when the row already says it. */
  label?: string;
};

/**
 * The small bouncing bars that mark what is playing in a list of tracks. Each bar keeps its own tempo so they never
 * line up; pausing settles them low and still. Under reduced motion the bars stand at rest heights.
 */
export function EqualizerBars({ playing = true, bars = 4, label, className, ...props }: EqualizerBarsProps) {
  const name = label ?? (playing ? "Playing" : "Paused");
  return (
    <span
      data-slot="equalizer-bars"
      data-playing={playing ? "" : undefined}
      className={cn("inline-flex h-3.5 items-end gap-[2px]", className)}
      {...(name ? { role: "img", "aria-label": name } : { "aria-hidden": true })}
      {...props}
    >
      {Array.from({ length: bars }, (_, i) => (
        <i key={i} style={{ "--eq-i": i } as CSSProperties} />
      ))}
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* equalizer-bars.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Equalizer bars: each bar its own tempo, so they never line up; paused bars settle low. */
  [data-slot="equalizer-bars"] { color: var(--accent); }
  [data-slot="equalizer-bars"] i { width: 3px; height: 100%; border-radius: 999px; background: currentColor; transform-origin: bottom; scale: 1 0.3; transition: scale var(--duration-deliberate) var(--ease-out); }
  [data-slot="equalizer-bars"][data-playing] i { animation: eq-bounce calc(0.62s + var(--eq-i) * 0.17s) var(--ease-in-out) calc(var(--eq-i) * -0.29s) infinite alternate; }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="equalizer-bars"][data-playing] i { animation: none; }
    [data-slot="equalizer-bars"][data-playing] i:nth-child(odd) { scale: 1 0.7; }
    [data-slot="equalizer-bars"][data-playing] i:nth-child(even) { scale: 1 0.45; }
  }
  @keyframes eq-bounce { 0% { scale: 1 0.25; } 35% { scale: 1 0.9; } 60% { scale: 1 0.45; } 100% { scale: 1 1; } }
}
